solution.javascript:
class _Node {
    constructor(key = 0, value = 0) {
        this.key = key;
        this.value = value;
        this.prev = null;
        this.next = null;
    }
}

class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.nodes = new Map();
        this.least = new _Node();
        this.most = new _Node();
        this.least.next = this.most;
        this.most.prev = this.least;
    }

    _remove(node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    _appendMostRecent(node) {
        const previous = this.most.prev;
        previous.next = node;
        node.prev = previous;
        node.next = this.most;
        this.most.prev = node;
    }

    get(key) {
        if (!this.nodes.has(key)) return -1;
        const node = this.nodes.get(key);
        this._remove(node);
        this._appendMostRecent(node);
        return node.value;
    }

    put(key, value) {
        if (this.nodes.has(key)) {
            const node = this.nodes.get(key);
            node.value = value;
            this._remove(node);
            this._appendMostRecent(node);
            return;
        }
        const node = new _Node(key, value);
        this.nodes.set(key, node);
        this._appendMostRecent(node);
        if (this.nodes.size > this.capacity) {
            const lru = this.least.next;
            this._remove(lru);
            this.nodes.delete(lru.key);
        }
    }
}
